      expect(await restarted.provider.getScaleOrderGroups()).toStrictEqual([
        expect.objectContaining({
          state: 'unknown',
          submittedSize: '0.001',
          childOrderIds: ['800'],
        }),
      ]);
      expect(restarted.calls).toStrictEqual([]);
      expect((await restarted.provider.placeOrder(intent)).success).toBe(false);
      expect(restarted.calls).toStrictEqual([]);
