      expect(
        await infra.diskCache.getItem('lighterNonceLedger:testnet:29:19'),
      ).toBe(original);
      await expect(
        built.provider.acknowledgeRecoveredDispatch(outcomes[1].recoveryId),
      ).rejects.toThrow('No pending recovered');
